function loadDatabase() {
  const data = localStorage.getItem(LOCAL_STORAGE_KEY);
  if (!data) {
    const initialDb = {
      projects: DEFAULT_PROJECTS,
      catalog: DEFAULT_CATALOG
    };
    saveDatabase(initialDb);
    return initialDb;
  }
  try {
    const db = JSON.parse(data);
    if (!db.catalog) {
      db.catalog = DEFAULT_CATALOG;
      saveDatabase(db);
    }
    return db;
  } catch (e) {
    console.error('Failed to parse local storage database, returning defaults', e);
    return { projects: DEFAULT_PROJECTS, catalog: DEFAULT_CATALOG };
  }
}

function saveDatabase(db) {
  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(db));
}

export const dbService = {
  // Projects Operations
  getProjects: () => {
    const db = loadDatabase();
    return db.projects || [];
  },

  getProjectById: (id) => {
    const db = loadDatabase();
    return (db.projects || []).find(p => p.id === id);
  },

  saveProject: (project) => {
    const db = loadDatabase();
    if (!db.projects) db.projects = [];

    const index = db.projects.findIndex(p => p.id === project.id);
    const updatedProject = {
      ...project,
      lastEdited: new Date().toISOString()
    };

    if (index >= 0) {
      db.projects[index] = updatedProject;
    } else {
      db.projects.push(updatedProject);
    }

    saveDatabase(db);
    return updatedProject;
  },

  deleteProject: (id) => {
    const db = loadDatabase();
    db.projects = (db.projects || []).filter(p => p.id !== id);
    saveDatabase(db);
  },

  // Catalog Operations
  getCatalog: () => {
    const db = loadDatabase();
    return db.catalog || DEFAULT_CATALOG;
  },

  saveCatalogItem: (item) => {
    const db = loadDatabase();
    if (!db.catalog) db.catalog = [...DEFAULT_CATALOG];

    const index = db.catalog.findIndex(c => c.id === item.id);
    if (index >= 0) {
      db.catalog[index] = item;
    } else {
      const newId = db.catalog.length > 0 ? Math.max(...db.catalog.map(x => x.id)) + 1 : 1;
      db.catalog.push({ ...item, id: newId });
    }

    saveDatabase(db);
  },

  deleteCatalogItem: (id) => {
    const db = loadDatabase();
    if (!db.catalog) db.catalog = [...DEFAULT_CATALOG];
    db.catalog = db.catalog.filter(c => c.id !== id);
    saveDatabase(db);
  },

  importCatalog: (items) => {
    if (!Array.isArray(items)) return;
    const db = loadDatabase();
    db.catalog = items;
    saveDatabase(db);
  },

  resetCatalog: () => {
    const db = loadDatabase();
    delete db.catalog;
    saveDatabase(db);
  },

  // Sync Settings
  getSyncConfig: () => {
    const config = localStorage.getItem(SYNC_CONFIG_KEY);
    let parsed = null;
    if (config) {
      try {
        parsed = JSON.parse(config);
      } catch {}
    }
    if (!parsed) {
      parsed = { repo: 'kemblek/magicsmoke', token: '', branch: 'main', path: 'great-balls-of-fire/public/projects.json' };
    }
    // Auto-update legacy data path to public path
    if (parsed.path === 'great-balls-of-fire/data/projects.json') {
      parsed.path = 'great-balls-of-fire/public/projects.json';
      localStorage.setItem(SYNC_CONFIG_KEY, JSON.stringify(parsed));
    }
    return parsed;
  },

  saveSyncConfig: (config) => {
    localStorage.setItem(SYNC_CONFIG_KEY, JSON.stringify(config));
  },

  // GitHub REST API Synchronization
  syncToGitHub: async (username = 'Planner') => {
    const config = dbService.getSyncConfig();
    if (!config.token) throw new Error('GitHub Personal Access Token is missing. Configure it in settings.');

    const url = `https://api.github.com/repos/${config.repo}/contents/${config.path}`;
    const headers = {
      'Authorization': `token ${config.token}`,
      'Accept': 'application/vnd.github.v3+json',
      'Content-Type': 'application/json'
    };

    // Get current file SHA if it exists
    let sha = '';
    try {
      const getRes = await fetch(url, { headers });
      if (getRes.status === 200) {
        const fileInfo = await getRes.json();
        sha = fileInfo.sha;
      }
    } catch (e) {
      console.warn('File not found on GitHub, creating a new one');
    }

    // Save current local DB to projects array representation
    const db = loadDatabase();
    const payload = {
      message: `Show Planning Sync by ${username}`,
      content: btoa(unescape(encodeURIComponent(JSON.stringify(db, null, 2)))),
      branch: config.branch
    };

    if (sha) {
      payload.sha = sha;
    }

    const putRes = await fetch(url, {
      method: 'PUT',
      headers,
      body: JSON.stringify(payload)
    });

    if (!putRes.ok) {
      const errText = await putRes.text();
      throw new Error(`GitHub upload failed: ${errText}`);
    }

    return true;
  },

  fetchFromGitHub: async () => {
    const config = dbService.getSyncConfig();
    let parsedDb = null;

    try {
      const localPath = window.location.pathname.endsWith('/') ? window.location.pathname : window.location.pathname + '/';
      const publicUrl = window.location.origin + localPath + 'projects.json';
      const res = await fetch(publicUrl, { cache: 'no-store' });
      if (res.ok) {
        parsedDb = await res.json();
        console.log('Successfully fetched database from public Pages path.');
      }
    } catch (e) {
      console.log('Public route fetch failed, falling back to GitHub API:', e);
    }

    if (!parsedDb) {
      const url = `https://api.github.com/repos/${config.repo}/contents/${config.path}?ref=${config.branch}`;
      const headers = {
        'Accept': 'application/vnd.github.v3+json'
      };
      if (config.token) {
        headers['Authorization'] = `token ${config.token}`;
      }

      const getRes = await fetch(url, { headers });
      if (!getRes.ok) {
        throw new Error(`GitHub fetch failed: status ${getRes.status}`);
      }

      const fileInfo = await getRes.json();
      const rawContent = decodeURIComponent(escape(atob(fileInfo.content)));
      parsedDb = JSON.parse(rawContent);
    }

    if (parsedDb && (parsedDb.projects || parsedDb.catalog)) {
      saveDatabase(parsedDb);
      if (parsedDb.token) {
        const config = dbService.getSyncConfig();
        if (!config.token) {
          config.token = parsedDb.token;
          dbService.saveSyncConfig(config);
        }
      }
      return true;
    } else {
      throw new Error('Invalid JSON format parsed from GitHub content.');
    }
  },

  fetchFromGitHubSilently: async () => {
    try {
      const config = dbService.getSyncConfig();
      let parsedDb = null;

      try {
        const localPath = window.location.pathname.endsWith('/') ? window.location.pathname : window.location.pathname + '/';
        const publicUrl = window.location.origin + localPath + 'projects.json';
        const res = await fetch(publicUrl, { cache: 'no-store' });
        if (res.ok) {
          parsedDb = await res.json();
        }
      } catch (e) {
        console.log('Silent public route fetch failed, falling back to GitHub API:', e);
      }

      if (!parsedDb) {
        const url = `https://api.github.com/repos/${config.repo}/contents/${config.path}?ref=${config.branch}`;
        const headers = {
          'Accept': 'application/vnd.github.v3+json'
        };
        if (config.token) {
          headers['Authorization'] = `token ${config.token}`;
        }

        const getRes = await fetch(url, { headers });
        if (!getRes.ok) return false;

        const fileInfo = await getRes.json();
        const rawContent = decodeURIComponent(escape(atob(fileInfo.content)));
        parsedDb = JSON.parse(rawContent);
      }

      if (parsedDb && (parsedDb.projects || parsedDb.catalog)) {
        const localRaw = localStorage.getItem(LOCAL_STORAGE_KEY);
        if (localRaw !== JSON.stringify(parsedDb)) {
          saveDatabase(parsedDb);
          if (parsedDb.token) {
            const config = dbService.getSyncConfig();
            if (!config.token) {
              config.token = parsedDb.token;
              dbService.saveSyncConfig(config);
            }
          }
          return true;
        }
      }
    } catch (e) {
      console.warn('Silent sync failed:', e);
    }
    return false;
  }
};
